import{_ as a,o as e,c as d,a3 as r}from"./chunks/framework.BlfGB29P.js";const _=JSON.parse('{"title":"是否采用元框架","description":"","frontmatter":{"title":"是否采用元框架","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/tooling/meta-framework.md","filePath":"frontend/decisions/tooling/meta-framework.md","lastUpdated":1785589115000}'),o={name:"frontend/decisions/tooling/meta-framework.md"};function i(l,t,h,n,s,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="是否采用元框架" tabindex="-1">是否采用元框架 <a class="header-anchor" href="#是否采用元框架" aria-label="Permalink to &quot;是否采用元框架&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>元框架在 UI 框架之上提供文件路由、数据加载、服务端渲染、静态生成、服务端入口、部署适配和约定。它能把跨端运行的复杂性收敛到统一模型，也会扩大框架和托管平台的影响范围。先决定页面渲染和运行时约束，再判断是否需要元框架。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>纯 SPA 可以用构建工具、路由和请求层组成，部署简单且边界明确。内容型、可索引、需要 SSR 或服务端动作的产品，如果自行拼装这些能力，需要长期维护路由匹配、数据去重、序列化、缓存和 Hydration。</p><p>决策不是“元框架功能多不多”，而是它承担的能力是否正好是产品的核心约束。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-硬约束" tabindex="-1">2.1 硬约束 <a class="header-anchor" href="#_2-1-硬约束" aria-label="Permalink to &quot;2.1 硬约束&quot;">​</a></h3><ul><li>支持已选 UI 框架、Node.js 和浏览器基线；</li><li>所需渲染模式、缓存和身份方案有稳定生产支持；</li><li>目标部署环境支持服务器 API、流和持久连接需求；</li><li>服务端代码和浏览器代码能被可靠隔离，敏感数据不会序列化到页面；</li><li>核心能力不依赖无法接受的实验性 API 或单一托管商私有服务。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>比较渲染需求覆盖、路由和数据模型、缓存可解释性、部署可移植、生态集成、升级节奏、调试、服务端能力和团队学习。还应比较“不采用”时自建组合的三年成本。</p><h2 id="_3-候选方案" tabindex="-1">3. 候选方案 <a class="header-anchor" href="#_3-候选方案" aria-label="Permalink to &quot;3. 候选方案&quot;">​</a></h2><h3 id="_3-1-spa-工具组合" tabindex="-1">3.1 SPA 工具组合 <a class="header-anchor" href="#_3-1-spa-工具组合" aria-label="Permalink to &quot;3.1 SPA 工具组合&quot;">​</a></h3><p>使用 Vite、客户端路由和独立 API。适合登录后的工具、SEO 无价值、已有后端和静态托管的场景。依赖少、部署清楚；当需要 SSR、预渲染和服务端数据编排时，自建成本会增长。</p><h3 id="_3-2-采用对应生态的元框架" tabindex="-1">3.2 采用对应生态的元框架 <a class="header-anchor" href="#_3-2-采用对应生态的元框架" aria-label="Permalink to &quot;3.2 采用对应生态的元框架&quot;">​</a></h3><p>Vue 可评估 Nuxt，React 可评估 Next.js、React Router 框架能力等。候选必须按路由数据、渲染、部署和版本支持逐项验证，不能只按 UI 框架自动绑定。</p><h3 id="_3-3-内容专用生成器或服务端模板" tabindex="-1">3.3 内容专用生成器或服务端模板 <a class="header-anchor" href="#_3-3-内容专用生成器或服务端模板" aria-label="Permalink to &quot;3.3 内容专用生成器或服务端模板&quot;">​</a></h3><p>文档、博客和低交互营销内容可能更适合 VitePress、Astro 等内容工具；已有服务端应用也可以继续服务端模板加局部交互。通用元框架不是所有可索引内容的唯一答案。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><p>案例是 Vue 3 客户门户，包含 2000 个公开帮助页面、可索引的产品详情、登录账户、服务端 Session 和个性化报价；团队原本计划用 SPA 加独立 Node BFF。</p><table tabindex="0"><thead><tr><th>维度</th><th>Vite SPA + BFF</th><th>Nuxt</th><th>内容站 + 独立 SPA</th></tr></thead><tbody><tr><td>混合渲染</td><td>需自行拼装</td><td>内建路由级能力</td><td>通过两个应用分工</td></tr><tr><td>Session SSR</td><td>自建协议</td><td>有统一服务端入口</td><td>只在账户 SPA/BFF</td></tr><tr><td>内容维护</td><td>需另建预渲染</td><td>可集成内容源</td><td>内容工具最强</td></tr><tr><td>部署单元</td><td>静态站 + BFF</td><td>一个逻辑应用，可多目标部署</td><td>两个应用</td></tr><tr><td>团队复杂度</td><td>自由但组合多</td><td>约定集中</td><td>导航、搜索和设计需跨站同步</td></tr><tr><td>锁定</td><td>组件层较低</td><td>路由和数据层较高</td><td>内容和账户各自锁定</td></tr></tbody></table><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>本案例采用 Nuxt，原因是公开内容、请求级报价和账户 Session 需要在同一路由体系中混合渲染。部署先使用标准 Node 适配，不把业务数据直接绑定到托管商专有存储。</p><p>如果产品只有登录后的运营后台，推荐 Vite SPA，不为无用的 SSR 引入元框架。若公开内容占绝大多数且账户只是独立入口，则内容站加 SPA 可能边界更清楚。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>采用元框架后，路由、数据加载、缓存和服务端入口获得统一约定，团队也承担框架升级、双端调试和部署适配。页面代码必须理解哪些逻辑运行在服务端、客户端或两端。</p><p>退出成本集中在文件路由、服务端动作、缓存 API 和数据序列化协议。领域服务和 HTTP 契约保持独立，能降低迁移成本；为了可移植而拒绝所有框架能力，则会失去采用元框架的主要收益。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>SEO、首屏 HTML 和服务端能力都不是需求的内部 SPA。</li><li>只是想获得文件路由时，可先评估客户端路由插件。</li><li>团队没有 Node.js 生产责任却选择需要服务端运行的模式。</li><li>关键功能依赖实验性 API，且没有降级或版本锁定策略。</li><li>内容站和业务应用生命周期完全不同，不必强行合并。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>Vue 客户门户是否采用元框架</td></tr><tr><td>硬约束</td><td>公开内容可索引；Session 不暴露；混合渲染；可部署到标准 Node</td></tr><tr><td>候选</td><td>Vite SPA + BFF、Nuxt、内容站 + 独立 SPA</td></tr><tr><td>决定</td><td>采用 Nuxt 和标准 Node 适配</td></tr><tr><td>关键证据</td><td>三类代表路由原型、缓存测试、部署演练、团队技能盘点</td></tr><tr><td>接受代价</td><td>双端运行复杂度；Nuxt 升级和路由数据锁定</td></tr><tr><td>明确不做</td><td>不使用平台私有数据库；后台管理仍保持独立 SPA</td></tr><tr><td>退出路径</td><td>领域 API 为普通 HTTP；内容源可导出；设计令牌跨应用共享</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>公开可索引内容被移除、SSR 运行成本持续超预算、关键部署目标停止支持、Hydration 错误超过质量门槛，或两个产品生命周期显著分离时复查。单个新框架版本发布不触发重新选型，只触发升级评估。</p>',33)])])}const p=a(o,[["render",i]]);export{_ as __pageData,p as default};
